from typing import Dict, List, Sequence, Tuple
from stockflow.first_fit_decreasing import first_fit_decreasing

def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be positive")
    merged: Dict[str, Tuple[int, int]] = {}
    for sku, qty, weight in lines:
        if qty <= 0 or weight <= 0:
            raise ValueError("qty and unit weight must be positive")
        if sku in merged and merged[sku][1] != weight:
            raise ValueError(f"SKU {sku} inconsistent weight")
        merged[sku] = (merged.get(sku, (0, weight))[0] + qty, weight)
    items: List[Tuple[str, int]] = []
    chunk_map: Dict[str, Tuple[str, int]] = {}
    cid = 0
    for sku, (qty, weight) in merged.items():
        if weight > max_parcel_grams:
            raise ValueError(f"SKU {sku} too heavy")
        u_per_c = max_parcel_grams // weight
        rem = qty
        while rem > 0:
            q = min(rem, u_per_c)
            cid_str = f"{cid}"
            items.append((cid_str, q * weight))
            chunk_map[cid_str] = (sku, q)
            cid += 1
            rem -= q
    bins = first_fit_decreasing(items, max_parcel_grams)
    res: List[Dict[str, int]] = []
    for b in bins:
        p = {}
        for cid_str, w in b:
            sku, q = chunk_map[cid_str]
            p[sku] = p.get(sku, 0) + q
        res.append(p)
    return res
